changeSet.sql:
INSERT INTO clinlims.system_privilege (name, description, category)
VALUES ('esig:use', 'Verify credentials for electronic signature', 'esig');

INSERT INTO clinlims.system_role_privilege (system_role_id, privilege_id)
SELECT r.id, (SELECT id FROM clinlims.system_privilege WHERE name = 'esig:use')
FROM clinlims.system_role r
WHERE trim(r.name) IN ('Pathologist', 'Cytopathologist', 'Validation');
